import re

def _scalar(tok):
    tok = tok.strip()
    if tok.startswith("[") and tok.endswith("]"):
        inner = tok[1:-1].strip()
        return [] if not inner else [_scalar(x) for x in inner.split(",")]
    if tok in ("true", "false"):
        return tok == "true"
    if tok in ("null", "~", ""):
        return None
    if re.fullmatch(r"-?\d+", tok):
        return int(tok)
    if len(tok) >= 2 and tok[0] == tok[-1] and tok[0] in "\"'":
        return tok[1:-1]
    return tok


def parse_yaml(text):
    """极简 YAML 子集解析器：映射 / 块列表 / 内联 flow 列表 / 标量。
    只求能读懂 workflow 文件（生产环境请用 PyYAML）。"""
    lines = []
    for raw in text.splitlines():
        s = raw.split("#", 1)[0].rstrip()
        if not s.strip():
            continue
        lines.append((len(s) - len(s.lstrip(" ")), s.strip()))

    def block(i, min_indent):
        if i >= len(lines) or lines[i][0] < min_indent:
            return None, i
        base = lines[i][0]
        if lines[i][1].startswith("-"):
            arr = []
            while i < len(lines) and lines[i][0] == base and lines[i][1].startswith("-"):
                rest = lines[i][1][1:].strip()
                i += 1
                if not rest:
                    val, i = block(i, base + 1)
                    arr.append(val)
                    continue
                key, sep, val = rest.partition(":")
                if sep:
                    item = {}
                    if val.strip():
                        item[key.strip()] = _scalar(val)
                    else:
                        item[key.strip()], i = block(i, base + 1)
                    if i < len(lines) and lines[i][0] > base:
                        sub, i = block(i, lines[i][0])
                        if isinstance(sub, dict):
                            item.update(sub)
                    arr.append(item)
                else:
                    arr.append(_scalar(rest))
            return arr, i
        d = {}
        while i < len(lines) and lines[i][0] == base and not lines[i][1].startswith("-"):
            key, sep, val = lines[i][1].partition(":")
            i += 1
            if val.strip():
                d[key.strip()] = _scalar(val)
            else:
                d[key.strip()], i = block(i, base + 1)
        return d, i

    doc, _ = block(0, 0)
    return doc

