PIN = re.compile(r"@v?\d")


def lint(wf):
    issues = []
    if "on" not in wf:
        issues.append(("WF001", "error", "workflow", "缺少 on 触发条件：workflow 永远不会被触发"))
    jobs = wf.get("jobs") or {}
    if not jobs:
        issues.append(("WF002", "error", "workflow", "缺少 jobs 或 jobs 为空"))
        return issues
    for name in sorted(jobs):
        job = jobs[name] or {}
        if "runs-on" not in job:
            issues.append(("WF003", "error", name, "缺少 runs-on：runner 类型未指定"))
        if "steps" not in job and "uses" not in job:
            issues.append(("WF004", "error", name, "既无 steps 也无 uses（可复用 workflow 才有 uses）"))
        steps = job.get("steps") or []
        if "steps" in job and not steps:
            issues.append(("WF004", "error", name, "steps 为空列表：job 什么都不做"))
        needs = job.get("needs") or []
        if isinstance(needs, str):
            needs = [needs]
        for n in needs:
            if n not in jobs:
                issues.append(("WF005", "error", name, "needs 引用了不存在的 job: %s" % n))
        for i, st in enumerate(steps, 1):
            if isinstance(st, dict) and "uses" in st and not PIN.search(str(st["uses"])):
                issues.append(("WF006", "warning", name, "step%d uses=%s 未固定版本（可被上游静默改动，建议 @v4 或提交 SHA）" % (i, st["uses"])))
        if "timeout-minutes" not in job:
            issues.append(("WF007", "warning", name, "未设置 timeout-minutes：挂死会占用 runner 默认 360 分钟"))
    return issues


for label, text, want_clean in (("正例 GOOD", GOOD, True), ("反例 BAD ", BAD, False)):
    wf = parse_yaml(text)
    jobs = sorted((wf.get("jobs") or {}))
    issues = lint(wf)
    print("[%s] 解析 job=%s 问题=%d 判定=%s" % (label, jobs, len(issues), "通过" if not issues else "不通过"))
    for code, sev, where, msg in sorted(issues):
        print("  %s %-7s job=%-7s %s" % (code, sev, where, msg))
    assert (not issues) == want_clean, "判定与预期不符: " + label

